// CBSE 10 Mathematics ch09 Some Applications of Trigonometry — practice bank with independent re-solve checks.
// Every height-and-distance answer is verified by REBUILDING THE SCENE: the claimed answers are placed as
// coordinates and the given angles are MEASURED back with atan2 (no tangent tables), and given lengths are
// measured by subtraction. Decimal answers use √3 ≈ 1.732 within the stated tolerance. At most two right
// triangles per item; angles 30°, 45°, 60° only. No item uses ratios of complementary angles (removed in ch08).
import { Q, caseQ, child, mk, r } from '../../cbse-10-mathematics-ch05/src/lib.mjs';
import { twoDepr } from './figs.mjs';

const S3 = Math.sqrt(3), S2 = Math.SQRT2;
const near = (u, v, e = 1e-9) => Math.abs(u - v) < e;
/** Angle (degrees) between the horizontal and the line from point a to point b. */
const ang = (a, b) => (Math.atan2(Math.abs(b[1] - a[1]), Math.abs(b[0] - a[0])) * 180) / Math.PI;
const is = (a, b, d) => near(ang(a, b), d, 1e-7);
const len = (a, b) => Math.hypot(b[0] - a[0], b[1] - a[1]);
/** Value with √3 replaced by 1.732 agrees with the exact value to the 2-decimal tolerance. */
const r2 = (v) => Math.round(v * 100) / 100;

const qLight = twoDepr({ h: 40, dNear: 40, dFar: 40 * S3, aNear: 45, aFar: 30, k: 0.05, height: '40 m' }, 'Lighthouse BT, 40 metres tall, drawn to scale, with two boats P and Q on the sea to one side. From the top T, a dashed horizontal and the lines of sight to the boats show angles of depression of 45 degrees to the nearer boat P and 30 degrees to the farther boat Q.', 'Angles of depression are measured from the horizontal at $T$ (drawn to scale).');

// =============================================================== MCQ
Q('m01', mk.mcq({ stem: 'From the top of a lighthouse, the angle of depression of a boat is $35^\\circ$. The angle of elevation of the top of the lighthouse from the boat is', opts: ['$35^\\circ$', '$55^\\circ$', '$145^\\circ$', '$90^\\circ$'], key: 'a', sol: r`The horizontal through the top of the lighthouse is parallel to the sea surface. The line of sight is a transversal, so the angle of depression at the top and the angle of elevation at the boat are **alternate angles**: both $35^\circ$. Option (b) measures the line of sight from the vertical.`, d: 2, c: 'understanding', t: [1], time: 45 }), (C) => { const T = [0, 10], P = [10 / Math.tan((35 * Math.PI) / 180), 0]; C.assert(is(T, P, 35) && is(P, T, 35), 'alternate angles'); C.key('a'); });
Q('m02', mk.mcq({ stem: 'As an observer walks straight towards a tower, the angle of elevation of its top', opts: ['increases', 'decreases', 'stays the same', 'first decreases, then increases'], key: 'a', sol: r`$\tan\theta = \dfrac{\text{height}}{\text{distance}}$. The height is fixed and the distance decreases, so $\tan\theta$ increases, and so does $\theta$.`, d: 1, c: 'understanding', t: [1], time: 45 }), (C) => { const T = [0, 30]; const a = [80, 50, 20, 5].map((x) => ang([x, 0], T)); C.assert(a.every((v, i) => i === 0 || v > a[i - 1]), 'increasing'); C.key('a'); });
Q('m03', mk.mcq({ stem: 'The angle of elevation of an object is the angle between', opts: ['the line of sight and the horizontal through the eye, when the object is above it', 'the line of sight and the vertical through the eye', 'the line of sight and the ground, when the object is below the eye', 'the horizontal and the vertical through the object'], key: 'a', sol: r`Angles of elevation and depression are always measured from the **horizontal** through the observer's eye: elevation when the object is above it, depression when below. Option (c) describes an angle of depression.`, d: 1, c: 'recall', t: [1], time: 45 }), (C) => C.key('a'));
Q('m04', mk.mcq({ stem: 'The angle of elevation of the top of a 30 m tower from a point P on the ground is $45^\\circ$. The distance of P from the foot of the tower is', opts: ['$30$ m', r`$30\sqrt3$ m`, r`$10\sqrt3$ m`, '$15$ m'], key: 'a', sol: r`$\tan 45^\circ = \dfrac{30}{d} = 1$, so $d = 30$ m. At $45^\circ$ the height and the distance are equal.`, d: 1, c: 'understanding', t: [2], time: 45 }), (C) => { const d = 30; C.assert(is([0, 0], [d, 30], 45), 'measured'); C.which([30, 30 * S3, 10 * S3, 15], d); });
Q('m05', mk.mcq({ stem: 'The shadow of a vertical pole is $\\sqrt3$ times as long as the pole. The angle of elevation of the sun is', opts: ['$30^\\circ$', '$60^\\circ$', '$45^\\circ$', '$90^\\circ$'], key: 'a', sol: r`$\tan\theta = \dfrac{\text{height}}{\text{shadow}} = \dfrac{h}{\sqrt3 h} = \dfrac{1}{\sqrt3}$, so $\theta = 30^\circ$. Option (b) inverts the ratio.`, d: 2, c: 'understanding', t: [2], time: 60 }), (C) => { const h = 7; C.which([30, 60, 45, 90], Math.round(ang([S3 * h, 0], [0, h]))); });
Q('m06', mk.mcq({ stem: 'A ramp $10$ m long makes an angle of $30^\\circ$ with the ground. The height of its top above the ground is', opts: ['$5$ m', r`$5\sqrt3$ m`, r`$10\sqrt3$ m`, '$20$ m'], key: 'a', sol: r`$\sin 30^\circ = \dfrac{h}{10}$, so $h = 10 \times \dfrac12 = 5$ m. Option (b) is the horizontal length ($10\cos 30^\circ$).`, d: 1, c: 'understanding', t: [2], time: 45 }), (C) => { const top = [10 * Math.cos(Math.PI / 6), 5]; C.assert(near(len([0, 0], top), 10) && is([0, 0], top, 30), 'ramp'); C.which([5, 5 * S3, 10 * S3, 20], top[1]); });
Q('m07', mk.mcq({ stem: 'From the top of a 9 m building, the angle of depression of a scooter parked on the road is $60^\\circ$. The distance of the scooter from the building is', opts: [r`$3\sqrt3$ m`, r`$9\sqrt3$ m`, '$3$ m', '$18$ m'], key: 'a', sol: r`$\tan 60^\circ = \dfrac{9}{d} \Rightarrow d = \dfrac{9}{\sqrt3} = 3\sqrt3 \approx 5.20$ m. Option (b) uses $\tan 30^\circ$ (the angle measured from the vertical).`, d: 2, c: 'application', t: [2], time: 75 }), (C) => { const d = 3 * S3; C.assert(is([0, 9], [d, 0], 60), 'measured'); C.which([3 * S3, 9 * S3, 3, 18], d); });
Q('m08', mk.mcq({ stem: 'A vertical pole casts a 12 m shadow when the angle of elevation of the sun is $60^\\circ$. The height of the pole is', opts: [r`$12\sqrt3$ m`, r`$4\sqrt3$ m`, '$6$ m', '$24$ m'], key: 'a', sol: r`$\tan 60^\circ = \dfrac{h}{12} \Rightarrow h = 12\sqrt3 \approx 20.78$ m. Option (b) divides by $\sqrt3$ instead of multiplying.`, d: 2, c: 'understanding', t: [2], time: 60 }), (C) => { const h = 12 * S3; C.assert(is([12, 0], [0, h], 60), 'measured'); C.which([12 * S3, 4 * S3, 6, 24], h); });
Q('m09', mk.mcq({ stem: 'When the angle of elevation of the sun rises from $30^\\circ$ to $60^\\circ$, the shadow of a 15 m pole becomes shorter by', opts: [r`$10\sqrt3$ m`, r`$15\sqrt3$ m`, r`$5\sqrt3$ m`, '$15$ m'], key: 'a', sol: r`Shadow at $30^\circ$: $\dfrac{15}{\tan 30^\circ} = 15\sqrt3$. At $60^\circ$: $\dfrac{15}{\sqrt3} = 5\sqrt3$. Shorter by $15\sqrt3 - 5\sqrt3 = 10\sqrt3 \approx 17.32$ m. Options (b) and (c) are the two shadows.`, d: 3, c: 'application', t: [2], time: 90 }), (C) => { const s1 = 15 * S3, s2 = 5 * S3; C.assert(is([s1, 0], [0, 15], 30) && is([s2, 0], [0, 15], 60), 'shadows'); C.which([10 * S3, 15 * S3, 5 * S3, 15], s1 - s2); });
Q('m10', mk.mcq({ stem: 'From a point on the ground 20 m from the foot of a building, the angle of elevation of its top is $60^\\circ$. The length of the line of sight from the point to the top is', opts: ['$40$ m', r`$20\sqrt3$ m`, '$10$ m', r`$40\sqrt3$ m`], key: 'a', sol: r`$\cos 60^\circ = \dfrac{20}{\text{line of sight}} \Rightarrow$ line of sight $= \dfrac{20}{1/2} = 40$ m. Option (b) is the height of the building.`, d: 2, c: 'application', t: [2], time: 75 }), (C) => { const T = [0, 20 * S3]; C.assert(is([20, 0], T, 60), 'measured'); C.which([40, 20 * S3, 10, 40 * S3], len([20, 0], T)); });
Q('m11', mk.mcq({ stem: 'A person whose eyes are 1.5 m above the ground stands 28.5 m from a tower and sees its top at an angle of elevation of $45^\\circ$. The height of the tower is', opts: ['$30$ m', '$28.5$ m', '$27$ m', '$31.5$ m'], key: 'a', sol: r`Above eye level the tower rises $28.5 \tan 45^\circ = 28.5$ m. Adding the eye height: $28.5 + 1.5 = 30$ m. Option (b) forgets the eye height; option (c) subtracts it.`, d: 2, c: 'application', t: [2], time: 75 }), (C) => { const H = 30; C.assert(is([0, 1.5], [28.5, H], 45), 'measured from the eye'); C.which([30, 28.5, 27, 31.5], H); });
Q('m12', mk.mcq({ stem: 'From the top of a 100 m cliff, the angle of depression of a boat is $45^\\circ$. The boat is at a distance of', opts: ['$100$ m', r`$100\sqrt3$ m`, r`$\dfrac{100}{\sqrt3}$ m`, r`$100\sqrt2$ m`], key: 'a', sol: r`$\tan 45^\circ = \dfrac{100}{d} = 1$, so $d = 100$ m. Option (d) is the length of the line of sight.`, d: 1, c: 'understanding', t: [2], time: 45 }), (C) => { C.assert(is([0, 100], [100, 0], 45), 'measured'); C.which([100, 100 * S3, 100 / S3, 100 * S2], 100); });
Q('m13', mk.mcq({ stem: 'The angle of elevation of the top of a 20 m pole from a point on the ground is $30^\\circ$. The distance from the point to the top of the pole is', opts: ['$40$ m', r`$20\sqrt3$ m`, '$10$ m', r`$\dfrac{40}{\sqrt3}$ m`], key: 'a', sol: r`$\sin 30^\circ = \dfrac{20}{\text{line of sight}}$, so the line of sight is $\dfrac{20}{1/2} = 40$ m. Option (b) is the distance along the ground.`, d: 2, c: 'application', t: [2], time: 75 }), (C) => { const P = [20 * S3, 0], T = [0, 20]; C.assert(is(P, T, 30), 'measured'); C.which([40, 20 * S3, 10, 40 / S3], len(P, T)); });
Q('m14', mk.mcq({ stem: 'A ladder leans against a wall and makes an angle of $60^\\circ$ with the ground. Its foot is 3.5 m from the wall. The length of the ladder is', opts: ['$7$ m', r`$3.5\sqrt3$ m`, r`$7\sqrt3$ m`, '$1.75$ m'], key: 'a', sol: r`$\cos 60^\circ = \dfrac{3.5}{l} \Rightarrow l = \dfrac{3.5}{1/2} = 7$ m. Option (b) is the height it reaches on the wall.`, d: 2, c: 'understanding', t: [2], time: 60 }), (C) => { const top = [0, 3.5 * S3]; C.assert(is([3.5, 0], top, 60), 'measured'); C.which([7, 3.5 * S3, 7 * S3, 1.75], len([3.5, 0], top)); });
Q('m15', mk.mcq({ stem: 'A hot-air balloon at the Pushkar fair is tied to the ground by a straight 200 m cable that makes an angle of $60^\\circ$ with the ground. The height of the balloon is', opts: [r`$100\sqrt3$ m`, '$100$ m', r`$200\sqrt3$ m`, r`$\dfrac{400}{\sqrt3}$ m`], key: 'a', sol: r`$\sin 60^\circ = \dfrac{h}{200} \Rightarrow h = 200 \times \dfrac{\sqrt3}{2} = 100\sqrt3 \approx 173.2$ m. Option (b) uses $\cos 60^\circ$.`, d: 2, c: 'application', t: [2], time: 75 }), (C) => { const B = [100, 100 * S3]; C.assert(near(len([0, 0], B), 200) && is([0, 0], B, 60), 'cable'); C.which([100 * S3, 100, 200 * S3, 400 / S3], B[1]); });
Q('m16', mk.mcq({ stem: 'P is on the ground and Q is at the top of a tower. Which statement is always true?', opts: ['The angle of depression of P from Q equals the angle of elevation of Q from P.', 'The angle of depression of P from Q is the complement of the angle of elevation of Q from P.', 'The angle of depression is always larger than the angle of elevation.', 'The two angles add up to $180^\\circ$.'], key: 'a', sol: r`The horizontal at $Q$ and the ground at $P$ are parallel, and the line $PQ$ crosses both, so the two angles are alternate angles and are equal.`, d: 2, c: 'understanding', t: [1], time: 60 }), (C) => { for (const [h, d] of [[10, 7], [40, 40], [5, 30]]) C.assert(near(ang([0, h], [d, 0]), ang([d, 0], [0, h])), `equal for ${h}, ${d}`); C.key('a'); });
Q('m17', mk.mcq({ stem: 'The shadow of a tower is 30 m longer when the sun’s elevation is $30^\\circ$ than when it is $60^\\circ$. The height of the tower is', opts: [r`$15\sqrt3$ m`, r`$30\sqrt3$ m`, r`$10\sqrt3$ m`, '$15$ m'], key: 'a', sol: r`$h\sqrt3 - \dfrac{h}{\sqrt3} = 30 \Rightarrow \dfrac{3h - h}{\sqrt3} = 30 \Rightarrow h = 15\sqrt3 \approx 25.98$ m.`, d: 3, c: 'application', t: [2], time: 120 }), (C) => { const h = 15 * S3; const s30 = h * S3, s60 = h / S3; C.assert(is([s30, 0], [0, h], 30) && is([s60, 0], [0, h], 60) && near(s30 - s60, 30), 'scene'); C.which([15 * S3, 30 * S3, 10 * S3, 15], h); });
Q('m18', mk.mcq({ stem: 'A student whose eyes are 1.6 m above the ground sees the top of a 31.6 m water tower at an angle of elevation of $60^\\circ$. Her distance from the tower is', opts: [r`$10\sqrt3$ m`, r`$30\sqrt3$ m`, r`$\dfrac{31.6}{\sqrt3}$ m`, '$10$ m'], key: 'a', sol: r`Above eye level the tower rises $31.6 - 1.6 = 30$ m. $\tan 60^\circ = \dfrac{30}{d} \Rightarrow d = \dfrac{30}{\sqrt3} = 10\sqrt3 \approx 17.32$ m. Option (c) forgets the eye height.`, d: 3, c: 'application', t: [2], time: 90 }), (C) => { const d = 10 * S3; C.assert(is([0, 1.6], [d, 31.6], 60), 'measured from the eye'); C.which([10 * S3, 30 * S3, 31.6 / S3, 10], d); });

// =============================================================== Assertion-reason (keys a b c d a d)
Q('ar1', mk.ar({ a: 'If the angle of elevation of the top of a tower from a point 50 m from its foot is $45^\\circ$, the tower is 50 m tall.', r: r`$\tan 45^\circ = 1$.`, key: 'a', sol: r`$\dfrac{h}{50} = \tan 45^\circ = 1$ (R), so $h = 50$ m (A). R explains A.`, d: 1, c: 'understanding', t: [2] }), (C) => { C.assert(is([0, 0], [50, 50], 45), '45'); C.key('a'); });
Q('ar2', mk.ar({ a: 'The angle of depression of a car from the top of a building equals the angle of elevation of the top of the building from the car.', r: r`$\tan 60^\circ = \sqrt3$.`, key: 'b', sol: r`A is true (alternate angles between parallel horizontals). R is a true value from the table, but it says nothing about why the two angles are equal.`, d: 1, c: 'understanding', t: [1] }), (C) => { C.assert(near(ang([0, 12], [9, 0]), ang([9, 0], [0, 12])), 'A'); C.key('b'); });
Q('ar3', mk.ar({ a: 'As the sun rises higher in the sky, the shadow of a vertical pole becomes shorter.', r: 'The tangent of an angle decreases as the angle increases from $0^\\circ$ to $90^\\circ$.', key: 'c', sol: r`A is true: shadow $= \dfrac{h}{\tan\theta}$, and $\tan\theta$ **increases** with $\theta$, so the shadow shrinks. R is false: $\tan 30^\circ < \tan 45^\circ < \tan 60^\circ$.`, d: 2, c: 'understanding', t: [2] }), (C) => { const sh = [30, 45, 60].map((t) => 10 / Math.tan((t * Math.PI) / 180)); C.assert(sh[0] > sh[1] && sh[1] > sh[2], 'shorter'); C.key('c'); });
Q('ar4', mk.ar({ a: 'When the sun’s elevation is $45^\\circ$, the shadow of a pole is longer than the pole.', r: 'The length of the shadow of a pole of height $h$, when the sun’s elevation is $\\theta$, is $\\dfrac{h}{\\tan\\theta}$.', key: 'd', sol: r`R is true. By R, at $45^\circ$ the shadow is $\dfrac{h}{1} = h$: equal to the pole, not longer. A is false.`, d: 2, c: 'application', t: [2] }), (C) => { C.assert(is([8, 0], [0, 8], 45), 'equal'); C.key('d'); });
Q('ar5', mk.ar({ a: 'From a point 30 m from the foot of a tower, the angle of elevation of its top is $30^\\circ$; so the tower is $10\\sqrt3$ m tall.', r: 'In the right triangle formed, the tangent of the angle of elevation equals the height divided by the distance.', key: 'a', sol: r`By R, $h = 30\tan 30^\circ = \dfrac{30}{\sqrt3} = 10\sqrt3$ m. R explains A.`, d: 2, c: 'application', t: [2] }), (C) => { C.assert(is([30, 0], [0, 10 * S3], 30), 'measured'); C.key('a'); });
Q('ar6', mk.ar({ a: 'If you halve your distance from a tower, the angle of elevation of its top doubles.', r: r`$\tan\theta = \dfrac{\text{height}}{\text{distance}}$.`, key: 'd', sol: r`R is true. Halving the distance doubles $\tan\theta$, not $\theta$. Example: a tower seen at $30^\circ$ from $h\sqrt3$; from $\dfrac{h\sqrt3}{2}$, $\tan\theta = \dfrac{2}{\sqrt3} \approx 1.15$, so $\theta \approx 49^\circ$, not $60^\circ$. A is false.`, d: 3, c: 'evaluation', t: [2] }), (C) => { const h = 10; const a1 = ang([h * S3, 0], [0, h]), a2 = ang([(h * S3) / 2, 0], [0, h]); C.assert(near(a1, 30) && Math.abs(a2 - 49.1) < 0.1 && !near(a2, 60), `${a2}`); C.key('d'); });

// =============================================================== True / false
Q('tf1', mk.tf({ stem: 'The angle of elevation of an object is measured from the vertical line through the observer.', key: 'f', sol: r`It is measured from the **horizontal** line through the observer's eye.`, d: 1, c: 'recall', t: [1] }), (C) => C.key('f'));
Q('tf2', mk.tf({ stem: 'An observer at the top of a tower sees objects on the ground below at angles of depression.', key: 't', sol: r`The objects are below the horizontal through the observer's eye, so the angles are angles of depression.`, d: 1, c: 'recall', t: [1] }), (C) => C.key('t'));
Q('tf3', mk.tf({ stem: 'When the sun’s elevation is $60^\\circ$, a 6 m pole casts a shadow $2\\sqrt3$ m long.', key: 't', sol: r`Shadow $= \dfrac{6}{\tan 60^\circ} = \dfrac{6}{\sqrt3} = 2\sqrt3 \approx 3.46$ m.`, d: 2, c: 'understanding', t: [2] }), (C) => { C.assert(is([2 * S3, 0], [0, 6], 60), 'measured'); C.key('t'); });
Q('tf4', mk.tf({ stem: 'If the top of a tower is seen at $30^\\circ$ from a point P, then from a point twice as far away (on the same line) it is seen at $15^\\circ$.', key: 'f', sol: r`Doubling the distance halves $\tan\theta$: from $\dfrac{1}{\sqrt3}$ to $\dfrac{1}{2\sqrt3} \approx 0.29$, an angle of about $16^\circ$, not $15^\circ$. Angles do not scale like distances.`, d: 3, c: 'analysis', t: [2] }), (C) => { const a2 = ang([2 * 10 * S3, 0], [0, 10]); C.assert(Math.abs(a2 - 16.1) < 0.1, `${a2}`); C.key('f'); });
Q('tf5', mk.tf({ stem: 'An angle of depression can be greater than $90^\\circ$.', key: 'f', sol: r`It is the angle between the horizontal and a line of sight below it, so it lies between $0^\circ$ and $90^\circ$.`, d: 1, c: 'understanding', t: [1] }), (C) => C.key('f'));

// =============================================================== Fill in the blank
Q('fb1', mk.fill({ stem: 'When the object is above the horizontal through the eye, the angle between the line of sight and that horizontal is called the angle of ___.', acc: [['elevation']], sol: 'Above the horizontal: elevation. Below: depression.', d: 1, c: 'recall', t: [1] }), (C) => C.blank('elevation'));
Q('fb2', mk.fill({ stem: 'The top of a 25 m tower is seen from a point P on the ground at an angle of elevation of $45^\\circ$. P is ___ m from the foot of the tower.', acc: [['25']], sol: r`$\tan 45^\circ = 1$, so the distance equals the height: $25$ m.`, d: 1, c: 'understanding', t: [2] }), (C) => { C.assert(is([25, 0], [0, 25], 45), 'measured'); C.blank(25); });
Q('fb3', mk.fill({ stem: 'A pole $10\\sqrt3$ m high casts a shadow 10 m long. The angle of elevation of the sun is ___ degrees.', acc: [['60', '60°']], sol: r`$\tan\theta = \dfrac{10\sqrt3}{10} = \sqrt3$, so $\theta = 60^\circ$.`, d: 2, c: 'understanding', t: [2] }), (C) => C.blank(Math.round(ang([10, 0], [0, 10 * S3]) * 1e9) / 1e9));
Q('fb4', mk.fill({ stem: 'From the top of a cliff, the angle of depression of a boat is $50^\\circ$. From the boat, the angle of elevation of the top of the cliff is ___ degrees.', acc: [['50', '50°']], sol: r`Alternate angles between the parallel horizontals: also $50^\circ$.`, d: 1, c: 'understanding', t: [1] }), (C) => { const T = [0, 30], P = [30 / Math.tan((50 * Math.PI) / 180), 0]; C.blank(Math.round(ang(P, T) * 1e9) / 1e9); });
Q('fb5', mk.fill({ stem: 'A ramp rises 2 m and makes an angle of $30^\\circ$ with the ground. Its length is ___ m.', acc: [['4']], sol: r`$\sin 30^\circ = \dfrac{2}{l} \Rightarrow l = 4$ m.`, d: 1, c: 'understanding', t: [2] }), (C) => { const foot = [-2 * S3, 0]; C.assert(is(foot, [0, 2], 30), 'measured'); C.blank(Math.round(len(foot, [0, 2]) * 1e9) / 1e9); });

// =============================================================== Numerical (√3 ≈ 1.732)
Q('n01', mk.num({ stem: 'From a point 40 m from the foot of a tree, the angle of elevation of its top is $30^\\circ$. Find the height of the tree in metres, correct to two decimal places. (Use $\\sqrt3 \\approx 1.732$.)', value: 23.09, tol: 0.01, unit: 'm', marks: 2, sol: r`**Step 1.** $\tan 30^\circ = \dfrac{h}{40} \Rightarrow h = \dfrac{40}{\sqrt3} = \dfrac{40\sqrt3}{3}$. **Step 2.** $h \approx \dfrac{40 \times 1.732}{3} = \dfrac{69.28}{3} \approx 23.09$ m.`, scheme: [['tan 30° = h/40', 1], ['23.09 m', 1]], d: 2, c: 'understanding', t: [2], time: 120 }), (C) => { const h = 40 / S3; C.assert(is([40, 0], [0, h], 30), 'measured'); C.val(h, 0.01); });
Q('n02', mk.num({ stem: 'A 15 m ladder leans against a wall, making an angle of $60^\\circ$ with the ground. How high up the wall does it reach? Give your answer in metres to two decimal places. (Use $\\sqrt3 \\approx 1.732$.)', value: 12.99, tol: 0.01, unit: 'm', marks: 2, sol: r`**Step 1.** $\sin 60^\circ = \dfrac{h}{15} \Rightarrow h = \dfrac{15\sqrt3}{2}$. **Step 2.** $h \approx 7.5 \times 1.732 = 12.99$ m.`, scheme: [['sin 60° = h/15', 1], ['12.99 m', 1]], d: 2, c: 'understanding', t: [2], time: 120 }), (C) => { const top = [0, 7.5 * S3], foot = [7.5, 0]; C.assert(near(len(foot, top), 15) && is(foot, top, 60), 'ladder'); C.val(top[1], 0.01); });
Q('n03', mk.num({ stem: 'From the top of a 35 m building, the angle of depression of a point on the ground is $45^\\circ$. How far is the point from the building (in metres)?', value: 35, unit: 'm', sol: r`$\tan 45^\circ = \dfrac{35}{d} = 1$, so $d = 35$ m.`, scheme: [['35 m', 1]], d: 1, c: 'understanding', t: [2], time: 45 }), (C) => { C.assert(is([0, 35], [35, 0], 45), 'measured'); C.val(35); });
Q('n04', mk.num({ stem: 'Find the length of the shadow of an 8 m pole when the angle of elevation of the sun is $30^\\circ$, in metres to two decimal places. (Use $\\sqrt3 \\approx 1.732$.)', value: 13.86, tol: 0.01, unit: 'm', marks: 2, sol: r`**Step 1.** $\tan 30^\circ = \dfrac{8}{s} \Rightarrow s = 8\sqrt3$. **Step 2.** $s \approx 8 \times 1.732 = 13.856 \approx 13.86$ m.`, scheme: [['tan 30° = 8/s', 1], ['13.86 m', 1]], d: 2, c: 'understanding', t: [2], time: 120 }), (C) => { const s = 8 * S3; C.assert(is([s, 0], [0, 8], 30), 'measured'); C.val(s, 0.01); });
Q('n05', mk.num({ stem: 'From two points 20 m apart on the same side of a tower, and in line with its foot, the angles of elevation of the top are $30^\\circ$ and $60^\\circ$. Find the height of the tower in metres to two decimal places. (Use $\\sqrt3 \\approx 1.732$.)', value: 17.32, tol: 0.01, unit: 'm', marks: 2, sol: r`**Step 1.** Let the height be $h$ and the nearer point be $x$ m from the foot. $\tan 60^\circ = \dfrac{h}{x} \Rightarrow x = \dfrac{h}{\sqrt3}$; $\tan 30^\circ = \dfrac{h}{x + 20} \Rightarrow x + 20 = h\sqrt3$. **Step 2.** $h\sqrt3 - \dfrac{h}{\sqrt3} = 20 \Rightarrow \dfrac{2h}{\sqrt3} = 20 \Rightarrow h = 10\sqrt3 \approx 17.32$ m.`, scheme: [['Two tan equations', 1], ['h = 10√3 ≈ 17.32 m', 1]], d: 3, c: 'application', t: [2], time: 180 }), (C) => { const h = 10 * S3, x = h / S3; C.assert(is([x, 0], [0, h], 60) && is([x + 20, 0], [0, h], 30) && near(x, 10), 'scene'); C.val(h, 0.01); });
Q('n06', mk.num({ stem: 'From the top of a 30 m tower, the angles of depression of two points on opposite sides of the tower, in line with its foot, are $45^\\circ$ and $60^\\circ$. Find the distance between the points in metres to two decimal places. (Use $\\sqrt3 \\approx 1.732$.)', value: 47.32, tol: 0.01, unit: 'm', marks: 2, sol: r`**Step 1.** At $45^\circ$: distance $= 30$ m. At $60^\circ$: distance $= \dfrac{30}{\sqrt3} = 10\sqrt3$ m. **Step 2.** Total $= 30 + 10\sqrt3 \approx 30 + 17.32 = 47.32$ m.`, scheme: [['Both distances', 1], ['47.32 m', 1]], d: 3, c: 'application', t: [2], time: 150 }), (C) => { const T = [0, 30], P = [-30, 0], Qp = [10 * S3, 0]; C.assert(is(T, P, 45) && is(T, Qp, 60), 'scene'); C.val(Qp[0] - P[0], 0.01); });
Q('n07', mk.num({ stem: 'A girl whose eyes are 1.5 m above the ground sees the top of a 21.5 m tree at an angle of elevation of $30^\\circ$. How far is she from the tree, in metres to two decimal places? (Use $\\sqrt3 \\approx 1.732$.)', value: 34.64, tol: 0.01, unit: 'm', marks: 2, sol: r`**Step 1.** Above eye level the tree rises $21.5 - 1.5 = 20$ m. **Step 2.** $\tan 30^\circ = \dfrac{20}{d} \Rightarrow d = 20\sqrt3 \approx 34.64$ m.`, scheme: [['Height above eye level 20 m', 1], ['34.64 m', 1]], d: 3, c: 'application', t: [2], time: 150 }), (C) => { const d = 20 * S3; C.assert(is([0, 1.5], [d, 21.5], 30), 'measured from the eye'); C.val(d, 0.01); });
Q('n08', mk.num({ stem: 'A 20 m mobile-phone antenna stands on the roof of a building. From a point on the ground, the angles of elevation of the bottom and the top of the antenna are $30^\\circ$ and $60^\\circ$. Find the height of the building in metres.', value: 10, unit: 'm', marks: 2, sol: r`**Step 1.** Let the building be $h$ m tall and the point $d$ m away. $\tan 30^\circ = \dfrac{h}{d} \Rightarrow d = h\sqrt3$. **Step 2.** $\tan 60^\circ = \dfrac{h + 20}{d} \Rightarrow h + 20 = \sqrt3 \times h\sqrt3 = 3h \Rightarrow h = 10$ m.`, scheme: [['d = h√3', 1], ['h = 10 m', 1]], d: 3, c: 'application', t: [2], time: 180 }), (C) => { const h = 10, d = 10 * S3; C.assert(is([d, 0], [0, h], 30) && is([d, 0], [0, h + 20], 60), 'scene'); C.val(h); });
Q('n09', mk.num({ stem: 'Find the angle of elevation (in degrees) of the top of a tower $50\\sqrt3$ m high from a point on the ground 50 m from its foot.', value: 60, unit: '°', sol: r`$\tan\theta = \dfrac{50\sqrt3}{50} = \sqrt3$, so $\theta = 60^\circ$.`, scheme: [['60°', 1]], d: 2, c: 'understanding', t: [2], time: 60 }), (C) => C.val(Math.round(ang([50, 0], [0, 50 * S3]) * 1e9) / 1e9));

// =============================================================== Short answer, 2 marks
Q('s201', mk.short({ marks: 2, stem: 'From a window 8 m above the ground, Ravi sees a car on the road at an angle of depression of $30^\\circ$. Draw a figure, mark the angle of depression and the equal angle of elevation, and find the distance of the car from the foot of the building.', model: r`Figure: a vertical $BW$ of height $8$ m ($W$ the window), the car $C$ on the ground, a dashed horizontal through $W$; the angle between the horizontal and $WC$ is $30^\circ$, and $\angle WCB = 30^\circ$ (alternate angles).

In right triangle $WBC$: $\tan 30^\circ = \dfrac{8}{BC} \Rightarrow BC = 8\sqrt3 \approx 13.86$ m.`, sol: 'The angle of depression at W equals the angle of elevation at C.', scheme: [['Correct figure with both angles marked', 1], ['BC = 8√3 ≈ 13.86 m', 1]], d: 2, c: 'application', t: [1, 2], time: 150 }), (C) => { const W = [0, 8], Cc = [8 * S3, 0]; C.assert(is(W, Cc, 30), 'measured'); C.model(['8\\sqrt3', 13.86]); });
Q('s202', mk.short({ marks: 2, stem: 'The angle of elevation of the top of a tower from a point 24 m from its foot is $60^\\circ$. Find the height of the tower.', model: r`$\tan 60^\circ = \dfrac{h}{24} \Rightarrow h = 24\sqrt3 \approx 41.57$ m.`, sol: r`$24 \times 1.732 = 41.568$.`, scheme: [['tan 60° = h/24', 1], ['24√3 ≈ 41.57 m', 1]], d: 2, c: 'understanding', t: [2], time: 90 }), (C) => { C.assert(is([24, 0], [0, 24 * S3], 60), 'measured'); C.model(['24\\sqrt3', 41.57]); });
Q('s203', mk.short({ marks: 2, stem: 'A tightrope is stretched from the top of a 12 m pole to a peg on the ground, making an angle of $30^\\circ$ with the ground. Find the length of the rope and the distance of the peg from the foot of the pole.', model: r`$\sin 30^\circ = \dfrac{12}{l} \Rightarrow l = 24$ m.

$\tan 30^\circ = \dfrac{12}{d} \Rightarrow d = 12\sqrt3 \approx 20.78$ m.`, sol: r`**Check:** $12^2 + (12\sqrt3)^2 = 144 + 432 = 576 = 24^2$.`, scheme: [['Rope 24 m', 1], ['Peg 12√3 ≈ 20.78 m', 1]], d: 2, c: 'understanding', t: [2], time: 120 }), (C) => { const peg = [12 * S3, 0], top = [0, 12]; C.assert(is(peg, top, 30) && near(len(peg, top), 24), 'rope'); C.model([24, '12\\sqrt3', 20.78]); });
Q('s204', mk.short({ marks: 2, stem: 'Find the angle of elevation of the sun when the shadow of a 6 m pole is $2\\sqrt3$ m long.', model: r`$\tan\theta = \dfrac{6}{2\sqrt3} = \dfrac{3}{\sqrt3} = \sqrt3$, so $\theta = 60^\circ$.`, sol: 'Height over shadow gives the tangent of the sun’s elevation.', scheme: [['tan θ = √3', 1], ['θ = 60°', 1]], d: 2, c: 'understanding', t: [2], time: 90 }), (C) => { C.assert(near(ang([2 * S3, 0], [0, 6]), 60), '60'); C.model(['\\sqrt3', '60^\\circ']); });
Q('s205', mk.short({ marks: 2, stem: 'From the top of a 30 m cliff, the angle of depression of a boat is $60^\\circ$. How far is the boat from the foot of the cliff?', model: r`$\tan 60^\circ = \dfrac{30}{d} \Rightarrow d = \dfrac{30}{\sqrt3} = 10\sqrt3 \approx 17.32$ m.`, sol: 'The angle of elevation of the cliff top from the boat is also 60°.', scheme: [['tan 60° = 30/d', 1], ['10√3 ≈ 17.32 m', 1]], d: 2, c: 'understanding', t: [2], time: 90 }), (C) => { C.assert(is([0, 30], [10 * S3, 0], 60), 'measured'); C.model(['10\\sqrt3', 17.32]); });
Q('s206', mk.short({ marks: 2, stem: 'From the top of a 45 m lighthouse, the angle of depression of a boat is $30^\\circ$. Priya marks the $30^\\circ$ between the lighthouse and the line of sight, and finds the distance as $45\\tan 30^\\circ = 15\\sqrt3$ m. Find her mistake and the correct distance.', model: r`The angle of depression is measured from the **horizontal**, not from the vertical lighthouse. Her angle at the top should be $60^\circ$ from the vertical, so her formula is wrong.

Correct: $\tan 30^\circ = \dfrac{45}{d} \Rightarrow d = 45\sqrt3 \approx 77.94$ m (three times her answer).`, sol: r`Her value $15\sqrt3 \approx 25.98$ m would mean an angle of depression of $60^\circ$.`, scheme: [['Identifies the horizontal as the reference', 1], ['45√3 ≈ 77.94 m', 1]], d: 3, c: 'evaluation', t: [1, 2], time: 150 }), (C) => { C.assert(is([0, 45], [45 * S3, 0], 30) && is([0, 45], [15 * S3, 0], 60), 'correct and hers'); C.model(['45\\sqrt3', 77.94]); C.sol([25.98]); });
Q('s207', mk.short({ marks: 2, stem: 'A ramp at a railway station in Bhopal rises 1.2 m and makes an angle of $30^\\circ$ with the ground. Find the length of the ramp and the horizontal distance it covers.', model: r`$\sin 30^\circ = \dfrac{1.2}{l} \Rightarrow l = 2.4$ m.

$\tan 30^\circ = \dfrac{1.2}{x} \Rightarrow x = 1.2\sqrt3 \approx 2.08$ m.`, sol: r`$1.2 \times 1.732 = 2.0784$.`, scheme: [['Length 2.4 m', 1], ['Horizontal 1.2√3 ≈ 2.08 m', 1]], d: 2, c: 'application', t: [2], time: 120 }), (C) => { const foot = [-1.2 * S3, 0], top = [0, 1.2]; C.assert(is(foot, top, 30) && near(len(foot, top), 2.4), 'ramp'); C.model([2.4, '1.2\\sqrt3', 2.08]); });
Q('s208', mk.short({ marks: 2, stem: 'Two points on the ground lie on opposite sides of a vertical pole, 60 m apart and in line with its foot. The angles of elevation of the top of the pole from them are $30^\\circ$ and $60^\\circ$. Find the height of the pole.', model: r`Distances from the foot: $h\sqrt3$ (at $30^\circ$) and $\dfrac{h}{\sqrt3}$ (at $60^\circ$).

$h\sqrt3 + \dfrac{h}{\sqrt3} = 60 \Rightarrow \dfrac{4h}{\sqrt3} = 60 \Rightarrow h = 15\sqrt3 \approx 25.98$ m.`, sol: r`**Check:** $15\sqrt3 \times \sqrt3 = 45$ and $\dfrac{15\sqrt3}{\sqrt3} = 15$; $45 + 15 = 60$ ✓.`, scheme: [['Equation h√3 + h/√3 = 60', 1], ['h = 15√3 ≈ 25.98 m', 1]], d: 3, c: 'application', t: [2], time: 150 }), (C) => { const h = 15 * S3; C.assert(is([-45, 0], [0, h], 30) && is([15, 0], [0, h], 60), 'scene'); C.model(['15\\sqrt3', 25.98]); C.sol([45, 15]); });
Q('s209', mk.short({ marks: 2, stem: 'From the top of a 40 m tower, a car on a straight road leading to the tower is seen at an angle of depression of $45^\\circ$, and a little later at $60^\\circ$. How far did the car travel between the two observations?', model: r`At $45^\circ$ the car is $40$ m from the foot; at $60^\circ$ it is $\dfrac{40}{\sqrt3} = \dfrac{40\sqrt3}{3}$ m.

Distance travelled $= 40 - \dfrac{40\sqrt3}{3} \approx 40 - 23.09 = 16.91$ m.`, sol: r`The angle of depression increases as the car approaches.`, scheme: [['Both distances', 1], ['≈ 16.91 m', 1]], d: 3, c: 'application', t: [2], time: 150 }), (C) => { const T = [0, 40]; const d1 = 40, d2 = 40 / S3; C.assert(is(T, [d1, 0], 45) && is(T, [d2, 0], 60), 'scene'); C.model([r2(d1 - d2), 23.09]); });

// =============================================================== Short answer, 3 marks
Q('s301', mk.short({ marks: 3, stem: 'The shadow of a vertical tower becomes 10 m shorter when the sun’s elevation rises from $45^\\circ$ to $60^\\circ$. Find the height of the tower.', model: r`At $45^\circ$ the shadow equals the height $h$; at $60^\circ$ it is $\dfrac{h}{\sqrt3}$.

$h - \dfrac{h}{\sqrt3} = 10 \Rightarrow h\left(\dfrac{\sqrt3 - 1}{\sqrt3}\right) = 10 \Rightarrow h = \dfrac{10\sqrt3}{\sqrt3 - 1}$.

Rationalising: $h = \dfrac{10\sqrt3(\sqrt3 + 1)}{2} = 5(3 + \sqrt3) = 15 + 5\sqrt3 \approx 23.66$ m.`, sol: r`**Check:** the shadows are $23.66$ m and $\dfrac{23.66}{1.732} \approx 13.66$ m, which differ by $10$ m.`, scheme: [['Both shadows in terms of h', 1], ['Equation and solving', 1], ['15 + 5√3 ≈ 23.66 m', 1]], d: 4, c: 'application', t: [2], time: 300 }), (C) => { const h = 15 + 5 * S3; C.assert(is([h, 0], [0, h], 45) && is([h / S3, 0], [0, h], 60) && near(h - h / S3, 10), 'scene'); C.model(['15 + 5\\sqrt3', 23.66]); C.sol([13.66]); });
Q('s302', mk.short({ marks: 3, stem: 'A 4 m signboard is fixed on top of a vertical pole. From a point P on the ground, the angles of elevation of the bottom and the top of the signboard are $30^\\circ$ and $45^\\circ$. Find the height of the pole.', model: r`Let the pole be $h$ m and P be $d$ m from it. $\tan 45^\circ = \dfrac{h + 4}{d} \Rightarrow d = h + 4$; $\tan 30^\circ = \dfrac{h}{d} \Rightarrow d = h\sqrt3$.

$h\sqrt3 = h + 4 \Rightarrow h = \dfrac{4}{\sqrt3 - 1} = \dfrac{4(\sqrt3 + 1)}{2} = 2(\sqrt3 + 1) \approx 5.46$ m.`, sol: r`P is then $h + 4 \approx 9.46$ m from the pole.`, scheme: [['Two equations', 1], ['h(√3 − 1) = 4', 1], ['2(√3 + 1) ≈ 5.46 m', 1]], d: 4, c: 'application', t: [2], time: 300 }), (C) => { const h = 2 * (S3 + 1), d = h + 4; C.assert(is([d, 0], [0, h], 30) && is([d, 0], [0, h + 4], 45), 'scene'); C.model(['2(\\sqrt3 + 1)', 5.46]); C.sol([9.46]); });
Q('s303', mk.short({ marks: 3, stem: 'Two buildings stand 50 m apart. From the top of the shorter one, which is 20 m tall, the angle of elevation of the top of the taller one is $30^\\circ$. Find the height of the taller building.', model: r`The horizontal from the top of the shorter building meets the taller one 20 m above the ground. Above that level, the taller building rises $50\tan 30^\circ = \dfrac{50}{\sqrt3} = \dfrac{50\sqrt3}{3} \approx 28.87$ m.

Height $= 20 + \dfrac{50\sqrt3}{3} \approx 48.87$ m.`, sol: 'Split the taller building at the level of the shorter one.', scheme: [['Horizontal at 20 m', 1], ['50/√3 ≈ 28.87 m', 1], ['≈ 48.87 m', 1]], d: 3, c: 'application', t: [2], time: 240 }), (C) => { const H = 20 + 50 / S3; C.assert(is([0, 20], [50, H], 30), 'measured'); C.model([28.87, 48.87]); });
Q('s304', mk.short({ marks: 3, stem: 'A sailor on the deck of a ship, 12 m above the water, sees the top of a cliff at an angle of elevation of $45^\\circ$ and its base at an angle of depression of $30^\\circ$. Find the distance of the ship from the cliff and the height of the cliff.', model: r`Depression of the base: $\tan 30^\circ = \dfrac{12}{d} \Rightarrow d = 12\sqrt3 \approx 20.78$ m.

Elevation of the top: above deck level the cliff rises $d\tan 45^\circ = 12\sqrt3$ m.

Height of the cliff $= 12 + 12\sqrt3 = 12(1 + \sqrt3) \approx 32.78$ m.`, sol: 'The horizontal at deck level splits the cliff into two parts.', scheme: [['d = 12√3', 1], ['Upper part 12√3', 1], ['Height 12(1 + √3) ≈ 32.78 m', 1]], d: 4, c: 'application', t: [2], time: 300 }), (C) => { const d = 12 * S3, H = 12 + 12 * S3; const eye = [0, 12]; C.assert(is(eye, [d, 0], 30) && is(eye, [d, H], 45), 'scene'); C.model(['12\\sqrt3', 20.78, 32.78]); });
Q('s305', mk.short({ marks: 3, stem: 'From the top of a 60 m tower, the angles of depression of the top and the bottom of a building are $30^\\circ$ and $60^\\circ$. Find the height of the building.', model: r`Bottom ($60^\circ$): distance between them $d = \dfrac{60}{\sqrt3} = 20\sqrt3$ m.

Top ($30^\circ$): the tower top is $d\tan 30^\circ = 20\sqrt3 \times \dfrac{1}{\sqrt3} = 20$ m above the building's top.

Height of the building $= 60 - 20 = 40$ m.`, sol: 'First find the gap between the buildings from the steeper line.', scheme: [['d = 20√3', 1], ['Difference 20 m', 1], ['40 m', 1]], d: 3, c: 'application', t: [2], time: 240 }), (C) => { const d = 20 * S3; const T = [0, 60]; C.assert(is(T, [d, 0], 60) && is(T, [d, 40], 30), 'scene'); C.model([20, 40]); });
Q('s306', mk.short({ marks: 3, stem: 'Arjun claims: "When the sun’s elevation falls from $60^\\circ$ to $30^\\circ$, the shadow of a pole doubles in length." Test his claim for a 9 m pole.', model: r`At $60^\circ$: shadow $= \dfrac{9}{\sqrt3} = 3\sqrt3 \approx 5.20$ m. At $30^\circ$: shadow $= 9\sqrt3 \approx 15.59$ m.

$\dfrac{9\sqrt3}{3\sqrt3} = 3$: the shadow **triples**, so his claim is wrong.

(For any pole, the ratio is $\dfrac{h\sqrt3}{h/\sqrt3} = 3$.)`, sol: 'Halving the angle does not halve the tangent.', scheme: [['Shadow at 60°', 1], ['Shadow at 30°', 1], ['Ratio 3: claim wrong', 1]], d: 3, c: 'evaluation', t: [2], time: 240 }), (C) => { const s60 = 9 / S3, s30 = 9 * S3; C.assert(is([s60, 0], [0, 9], 60) && is([s30, 0], [0, 9], 30) && near(s30 / s60, 3), 'triples'); C.model(['3\\sqrt3', 5.2, 15.59, 3]); });
Q('s307', mk.short({ marks: 3, stem: 'A boat sails straight towards a 50 m lighthouse. The angle of depression of the boat from the top changes from $30^\\circ$ to $60^\\circ$ in 2 minutes. Find the speed of the boat in metres per minute.', model: r`Distances from the foot: $50\sqrt3$ (at $30^\circ$) and $\dfrac{50}{\sqrt3}$ (at $60^\circ$).

Distance sailed $= 50\sqrt3 - \dfrac{50}{\sqrt3} = \dfrac{150 - 50}{\sqrt3} = \dfrac{100}{\sqrt3} \approx 57.74$ m.

Speed $= \dfrac{57.74}{2} \approx 28.87$ m per minute.`, sol: 'Distance first, then divide by time.', scheme: [['Both distances', 1], ['100/√3 ≈ 57.74 m', 1], ['≈ 28.87 m/min', 1]], d: 3, c: 'application', t: [2], time: 300 }), (C) => { const T = [0, 50]; const d1 = 50 * S3, d2 = 50 / S3; C.assert(is(T, [d1, 0], 30) && is(T, [d2, 0], 60) && near(d1 - d2, 100 / S3), 'scene'); C.model([57.74, 28.87]); });

// =============================================================== Long answer, 5 marks
Q('l01', mk.long({ stem: `From two points A and B on the same side of a clock tower in Dehradun, and in line with its foot F, the angles of elevation of the top T are $30^\\circ$ and $60^\\circ$. A and B are 50 m apart.

(a) Draw a labelled figure.
(b) Find the height of the tower.
(c) Find the distance of B from the foot.
(d) Find the length of the line of sight from A to the top.`, model: r`(a) Figure: vertical $FT$; $A$ and $B$ on the ground on the same side, $B$ nearer, $AB = 50$ m; angles $\angle TAF = 30^\circ$ and $\angle TBF = 60^\circ$; right angle at $F$.

(b) Let $FT = h$, $BF = x$. $\tan 60^\circ = \dfrac{h}{x} \Rightarrow h = x\sqrt3$. $\tan 30^\circ = \dfrac{h}{x + 50} \Rightarrow x + 50 = h\sqrt3 = 3x \Rightarrow x = 25$. So $h = 25\sqrt3 \approx 43.30$ m.

(c) $BF = 25$ m.

(d) $\sin 30^\circ = \dfrac{h}{AT} \Rightarrow AT = 2h = 50\sqrt3 \approx 86.60$ m.`, sol: r`Notice $AB = BT = 50$ m: triangle $ABT$ is isosceles, because $\angle ATB = 60^\circ - 30^\circ = 30^\circ = \angle TAB$.`, scheme: [['Figure with both angles and right angle', 1], ['Two equations', 1], ['h = 25√3 ≈ 43.30 m', 1], ['BF = 25 m', 1], ['AT = 50√3 ≈ 86.60 m', 1]], d: 3, c: 'application', t: [1, 2], time: 600 }), (C) => { const h = 25 * S3, F = [0, 0], T = [0, h], B = [-25, 0], A = [-75, 0]; C.assert(is(A, T, 30) && is(B, T, 60) && near(B[0] - A[0], 50) && near(len(B, T), 50), 'scene'); C.model(['25\\sqrt3', 43.3, 25, '50\\sqrt3', 86.6]); });
Q('l02', mk.long({ stem: `Building P is 20 m tall. From the foot of P, the angle of elevation of the top of a taller building Q is $60^\\circ$; from the top of P, the angle of elevation of the top of Q is $45^\\circ$.

(a) Draw a labelled figure.
(b) Find the distance between the buildings.
(c) Find the height of Q.
(d) Find how much taller Q is than P.`, model: r`(a) Figure: verticals $P$ ($20$ m) and $Q$ ($H$ m), $d$ m apart; from the foot of $P$ a line to the top of $Q$ at $60^\circ$; from the top of $P$ a dashed horizontal and a line to the top of $Q$ at $45^\circ$.

(b) From the foot: $H = d\tan 60^\circ = d\sqrt3$. From the top: $H - 20 = d\tan 45^\circ = d$. So $d\sqrt3 - d = 20 \Rightarrow d = \dfrac{20}{\sqrt3 - 1} = 10(\sqrt3 + 1) \approx 27.32$ m.

(c) $H = d\sqrt3 = 10(3 + \sqrt3) \approx 47.32$ m.

(d) $H - 20 = d \approx 27.32$ m.`, sol: r`Rationalise: $\dfrac{20}{\sqrt3 - 1} \times \dfrac{\sqrt3 + 1}{\sqrt3 + 1} = \dfrac{20(\sqrt3 + 1)}{2}$.`, scheme: [['Figure', 1], ['Two equations', 1], ['d = 10(√3 + 1) ≈ 27.32 m', 1], ['H = 10(3 + √3) ≈ 47.32 m', 1], ['Difference ≈ 27.32 m', 1]], d: 4, c: 'application', t: [1, 2], time: 660 }), (C) => { const d = 10 * (S3 + 1), H = 10 * (3 + S3); C.assert(is([0, 0], [d, H], 60) && is([0, 20], [d, H], 45), 'scene'); C.model(['10(\\sqrt3 + 1)', 27.32, '10(3 + \\sqrt3)', 47.32]); });
Q('l03', mk.long({ stem: `A hot-air balloon at the Pushkar fair rises vertically from a point O on the ground. Seema watches from a point S on level ground, 100 m from O. The angle of elevation of the balloon changes from $30^\\circ$ to $60^\\circ$ in 2 minutes.

(a) Find the heights of the balloon at the two moments.
(b) How far did it rise?
(c) Find its average speed of rising in metres per minute.
(d) Find the distance of the balloon from Seema at the second moment.`, model: r`(a) $h_1 = 100\tan 30^\circ = \dfrac{100}{\sqrt3} \approx 57.74$ m; $h_2 = 100\tan 60^\circ = 100\sqrt3 \approx 173.21$ m.

(b) Rise $= 100\sqrt3 - \dfrac{100}{\sqrt3} = \dfrac{200}{\sqrt3} \approx 115.47$ m.

(c) Speed $= \dfrac{115.47}{2} \approx 57.74$ m per minute.

(d) Distance from Seema $= \dfrac{100}{\cos 60^\circ} = 200$ m.`, sol: r`The rise is exactly twice the first height, since $100\sqrt3 = 3 \times \dfrac{100}{\sqrt3}$.`, scheme: [['h₁ = 100/√3', 1], ['h₂ = 100√3', 1], ['Rise ≈ 115.47 m', 1], ['≈ 57.74 m/min', 1], ['200 m', 1]], d: 3, c: 'application', t: [2], time: 600 }), (C) => { const S = [100, 0], h1 = 100 / S3, h2 = 100 * S3; C.assert(is(S, [0, h1], 30) && is(S, [0, h2], 60) && near(len(S, [0, h2]), 200), 'scene'); C.model([57.74, 173.21, 115.47, 200]); });
Q('l04', mk.long({ stem: `From a point P on level ground, the angle of elevation of the top T of a vertical tower is $60^\\circ$. From a window Q, 20 m vertically above P, the angle of elevation of T is $30^\\circ$.

(a) Draw a labelled figure.
(b) Find the horizontal distance between P and the tower.
(c) Find the height of the tower.
(d) Find QT, and show that triangle PQT is isosceles.`, model: r`(a) Figure: $P$ on the ground, $Q$ 20 m above $P$, tower $BT$ at distance $d$; from $P$ the line $PT$ at $60^\circ$ to the ground; from $Q$ a dashed horizontal meeting $BT$ at $M$ (20 m up) and $QT$ at $30^\circ$ to it.

(b) From $P$: $H = d\sqrt3$. From $Q$: $H - 20 = \dfrac{d}{\sqrt3}$. Subtracting: $d\sqrt3 - \dfrac{d}{\sqrt3} = 20 \Rightarrow \dfrac{2d}{\sqrt3} = 20 \Rightarrow d = 10\sqrt3 \approx 17.32$ m.

(c) $H = 10\sqrt3 \times \sqrt3 = 30$ m.

(d) $QT = \dfrac{d}{\cos 30^\circ} = \dfrac{10\sqrt3}{\sqrt3/2} = 20$ m $= PQ$. So triangle $PQT$ is isosceles with $PQ = QT = 20$ m. (Also $\angle QPT = 90^\circ - 60^\circ = 30^\circ$ and $\angle QTP = 60^\circ - 30^\circ = 30^\circ$: equal base angles.)`, sol: r`**Check:** $PT = \dfrac{d}{\cos 60^\circ} = 20\sqrt3$, and the isosceles triangle with sides $20, 20, 20\sqrt3$ has apex angle $120^\circ$ at $Q$.`, scheme: [['Figure with both angles', 1], ['Two equations in d and H', 1], ['d = 10√3', 1], ['H = 30 m', 1], ['QT = 20 = PQ, isosceles', 1]], d: 5, c: 'analysis', t: [1, 2], time: 720 }), (C) => { const d = 10 * S3, P = [0, 0], Qw = [0, 20], T = [d, 30]; C.assert(is(P, T, 60) && is(Qw, T, 30) && near(len(Qw, T), 20) && near(len(P, T), 20 * S3), 'scene'); C.model(['10\\sqrt3', 17.32, 30, 20]); });
Q('l05', mk.long({ stem: `A 12 m vertical pole stands on level ground in Jaipur.

(a) Find the length of its shadow when the sun’s elevation is $30^\\circ$, $45^\\circ$ and $60^\\circ$.
(b) By how much does the shadow shorten as the elevation rises from $30^\\circ$ to $60^\\circ$?
(c) At what elevation is the shadow as long as the pole?
(d) Can the shadow ever be shorter than half the pole while the sun’s elevation is at most $60^\\circ$? Justify.`, model: r`(a) Shadow $= \dfrac{12}{\tan\theta}$: at $30^\circ$, $12\sqrt3 \approx 20.78$ m; at $45^\circ$, $12$ m; at $60^\circ$, $\dfrac{12}{\sqrt3} = 4\sqrt3 \approx 6.93$ m.

(b) $12\sqrt3 - 4\sqrt3 = 8\sqrt3 \approx 13.86$ m.

(c) Shadow $=$ pole when $\tan\theta = 1$, i.e. at $45^\circ$.

(d) The shadow is shortest when the elevation is largest. At $60^\circ$ it is $4\sqrt3 \approx 6.93$ m, which is more than half the pole ($6$ m). So for elevations up to $60^\circ$ the shadow is never shorter than half the pole.`, sol: r`For the shadow to be $6$ m we would need $\tan\theta = 2$, an elevation above $60^\circ$ (since $\tan 60^\circ \approx 1.73 < 2$).`, scheme: [['Three shadows', 1], ['Shortening 8√3 ≈ 13.86 m', 1], ['45°', 1], ['Shortest at 60°: 4√3 ≈ 6.93 m', 1], ['Conclusion: no', 1]], d: 4, c: 'evaluation', t: [2], time: 660 }), (C) => { const sh = [30, 45, 60].map((t) => 12 / Math.tan((t * Math.PI) / 180)); C.assert(near(sh[0], 12 * S3) && near(sh[1], 12) && near(sh[2], 4 * S3) && sh[2] > 6, 'shadows'); C.model([20.78, 12, 6.93, 13.86, '45^\\circ']); });
Q('l06', mk.long({ stem: `A helicopter hovers 300 m above a point P on a straight highway. From the helicopter, the angles of depression of two milestones A and B on the highway, on opposite sides of P, are $60^\\circ$ and $45^\\circ$.

(a) Draw a labelled figure.
(b) Find PA and PB.
(c) Find the distance AB.
(d) Which milestone is nearer to P, and by how much?`, model: r`(a) Figure: the helicopter $H$ vertically above $P$, $HP = 300$ m; $A$ and $B$ on the road on opposite sides of $P$; a dashed horizontal through $H$; angles of depression $60^\circ$ (to $A$) and $45^\circ$ (to $B$).

(b) $PA = \dfrac{300}{\tan 60^\circ} = \dfrac{300}{\sqrt3} = 100\sqrt3 \approx 173.2$ m; $PB = \dfrac{300}{\tan 45^\circ} = 300$ m.

(c) $AB = 300 + 100\sqrt3 \approx 473.2$ m.

(d) $A$ is nearer (larger angle of depression), by $300 - 100\sqrt3 \approx 126.8$ m.`, sol: r`The steeper the line of sight, the nearer the object.`, scheme: [['Figure', 1], ['PA = 100√3 m', 1], ['PB = 300 m', 1], ['AB ≈ 473.2 m', 1], ['A nearer by ≈ 126.8 m', 1]], d: 3, c: 'application', t: [1, 2], time: 600 }), (C) => { const Hh = [0, 300], A = [-100 * S3, 0], B = [300, 0]; C.assert(is(Hh, A, 60) && is(Hh, B, 45), 'scene'); C.model(['100\\sqrt3', 173.2, 300, 473.2, 126.8]); });

// =============================================================== Case-based
caseQ('c01', {
  passage: 'During a school trip to Delhi, Ananya, whose eyes are 1.5 m above the ground, looks at the top of a 72.5 m tall minaret from a point on level ground. The angle of elevation of the top is $45^\\circ$.',
  d: 3, c: 'application',
  model: r`(a) Option (b). (b) $71$ m. (c) (i) She walks back about $51.97$ m. Or (ii) $71\sqrt2 \approx 100.4$ m.`,
  sol: r`Above eye level the minaret rises $72.5 - 1.5 = 71$ m; at $45^\circ$ her distance is $71$ m. At $30^\circ$ she would be $71\sqrt3 \approx 122.97$ m away.`,
  children: [
    child('a', mk.mcq({ stem: 'The angle of elevation is measured between her line of sight and', opts: ['the minaret', 'the horizontal through her eyes', 'the ground at the foot of the minaret', 'the vertical through her eyes'], key: 'b', sol: r`Angles of elevation are measured from the horizontal through the observer's eye. That is why her eye height must be subtracted.`, d: 1, c: 'recall', t: [1], time: 45 })),
    child('b', mk.num({ stem: 'How far is she from the minaret (in metres)?', value: 71, unit: 'm', sol: r`Height above eye level $= 72.5 - 1.5 = 71$ m. $\tan 45^\circ = \dfrac{71}{d} \Rightarrow d = 71$ m.`, scheme: [['71 m', 1]], d: 2, c: 'application', t: [2], time: 75 })),
    child('c', mk.short({ marks: 2, stem: '**(i)** She walks straight back until the angle of elevation is $30^\\circ$. How far does she walk? (Use $\\sqrt3 \\approx 1.732$.)', model: r`At $30^\circ$: distance $= 71\sqrt3 \approx 122.97$ m.

She walks $71\sqrt3 - 71 = 71(\sqrt3 - 1) \approx 71 \times 0.732 \approx 51.97$ m.`, sol: 'Subtract the two distances.', scheme: [['71√3 m', 1], ['≈ 51.97 m', 1]], d: 3, c: 'application', t: [2], time: 150 }), [
      mk.short({ marks: 2, stem: '**(ii)** From her first position, how long is her line of sight to the top of the minaret?', model: r`$\cos 45^\circ = \dfrac{71}{\text{line of sight}} \Rightarrow$ line of sight $= 71\sqrt2 \approx 71 \times 1.414 \approx 100.4$ m.`, sol: 'The line of sight is the hypotenuse.', scheme: [['cos 45° relation', 1], ['≈ 100.4 m', 1]], d: 2, c: 'application', t: [2], time: 120 }),
    ]),
  ],
}, (C) => { const E = [0, 1.5], top = [71, 72.5]; C.child('a').key('b'); C.child('b').assert(is(E, top, 45), '45 from eye'); C.child('b').val(71); C.child('c').assert(is([-(71 * S3 - 71), 1.5], top, 30), '30 after walking back'); C.child('c').model([122.97, 51.97]); C.child('cii').assert(near(len(E, top), 71 * S2), 'sight'); C.child('cii').model([100.4]); C.model([71, 51.97, 100.4]); });

caseQ('c02', {
  passage: 'From the top T of a 40 m lighthouse at Kollam, two fishing boats P and Q, due west of the lighthouse and in line with its foot B, are seen at angles of depression of $45^\\circ$ and $30^\\circ$. The figure is drawn to scale.',
  assets: [qLight], d: 3, c: 'application',
  model: r`(a) Option (a): $40$ m. (b) $69.28$ m. (c) (i) $40(\sqrt3 - 1) \approx 29.28$ m. Or (ii) $\dfrac{80}{\sqrt3} \approx 46.19$ m.`,
  sol: r`$BP = 40$ m (at $45^\circ$), $BQ = 40\sqrt3 \approx 69.28$ m (at $30^\circ$).`,
  children: [
    child('a', mk.mcq({ stem: 'The distance of the nearer boat P from the foot B is', opts: ['$40$ m', r`$40\sqrt3$ m`, r`$\dfrac{40}{\sqrt3}$ m`, r`$40\sqrt2$ m`], key: 'a', sol: r`$\tan 45^\circ = \dfrac{40}{BP} = 1$, so $BP = 40$ m. Option (d) is the line of sight $TP$.`, d: 1, c: 'understanding', t: [2], time: 45 })),
    child('b', mk.num({ stem: 'Find the distance of the farther boat Q from B, in metres to two decimal places. (Use $\\sqrt3 \\approx 1.732$.)', value: 69.28, tol: 0.01, unit: 'm', sol: r`$\tan 30^\circ = \dfrac{40}{BQ} \Rightarrow BQ = 40\sqrt3 \approx 69.28$ m.`, scheme: [['69.28 m', 1]], d: 2, c: 'understanding', t: [2], time: 75 })),
    child('c', mk.short({ marks: 2, stem: '**(i)** Find the distance between the two boats.', model: r`$PQ = BQ - BP = 40\sqrt3 - 40 = 40(\sqrt3 - 1) \approx 40 \times 0.732 = 29.28$ m.`, sol: 'Both boats are on the same side, so subtract.', scheme: [['BQ − BP', 1], ['≈ 29.28 m', 1]], d: 2, c: 'application', t: [2], time: 120 }), [
      mk.short({ marks: 2, stem: '**(ii)** Later, boat Q has sailed straight towards the lighthouse and is seen at an angle of depression of $60^\\circ$. How far has it sailed?', model: r`Now $BQ' = \dfrac{40}{\tan 60^\circ} = \dfrac{40}{\sqrt3} \approx 23.09$ m.

Distance sailed $= 40\sqrt3 - \dfrac{40}{\sqrt3} = \dfrac{120 - 40}{\sqrt3} = \dfrac{80}{\sqrt3} \approx 46.19$ m.`, sol: 'Larger angle of depression, nearer boat.', scheme: [['New distance 40/√3', 1], ['≈ 46.19 m', 1]], d: 3, c: 'application', t: [2], time: 150 }),
    ]),
  ],
}, (C) => { const T = [0, 40]; C.child('a').which([40, 40 * S3, 40 / S3, 40 * S2], 40); C.child('a').assert(is(T, [40, 0], 45), 'P'); C.child('b').assert(is(T, [40 * S3, 0], 30), 'Q'); C.child('b').val(40 * S3, 0.01); C.child('c').model([29.28]); C.child('cii').assert(is(T, [40 / S3, 0], 60), 'Q later'); C.child('cii').model([23.09, 46.19]); C.model([40, 69.28, 29.28, 46.19]); });

caseQ('c03', {
  passage: 'At an adventure park in Rishikesh, a straight zip-line runs from the top of a 30 m platform down to a landing point on level ground. The angle of depression of the landing point from the top of the platform is $30^\\circ$.',
  d: 3, c: 'application',
  model: r`(a) Option (c): $60$ m. (b) $51.96$ m. (c) (i) $30\sqrt2 \approx 42.43$ m. Or (ii) $15$ m.`,
  sol: r`The zip-line makes $30^\circ$ with the horizontal: length $= \dfrac{30}{\sin 30^\circ} = 60$ m, horizontal distance $= 30\sqrt3 \approx 51.96$ m.`,
  children: [
    child('a', mk.mcq({ stem: 'The length of the zip-line is', opts: [r`$30\sqrt3$ m`, r`$20\sqrt3$ m`, '$60$ m', '$15$ m'], key: 'c', sol: r`$\sin 30^\circ = \dfrac{30}{l} \Rightarrow l = 60$ m. Option (a) is the horizontal distance.`, d: 2, c: 'understanding', t: [2], time: 60 })),
    child('b', mk.num({ stem: 'How far is the landing point from the foot of the platform (in metres, to two decimal places)? (Use $\\sqrt3 \\approx 1.732$.)', value: 51.96, tol: 0.01, unit: 'm', sol: r`$\tan 30^\circ = \dfrac{30}{d} \Rightarrow d = 30\sqrt3 \approx 51.96$ m.`, scheme: [['51.96 m', 1]], d: 2, c: 'understanding', t: [2], time: 75 })),
    child('c', mk.short({ marks: 2, stem: '**(i)** A second zip-line from the same platform lands where the angle of depression is $45^\\circ$. How long is it? (Use $\\sqrt2 \\approx 1.414$.)', model: r`$\sin 45^\circ = \dfrac{30}{l} \Rightarrow l = 30\sqrt2 \approx 42.43$ m.`, sol: 'Steeper line, shorter zip-line.', scheme: [['sin 45° relation', 1], ['≈ 42.43 m', 1]], d: 2, c: 'application', t: [2], time: 120 }), [
      mk.short({ marks: 2, stem: '**(ii)** A rider on the first zip-line has travelled half its length. How high above the ground is the rider?', model: r`Half the length is $30$ m along a line at $30^\circ$ below the horizontal, so the rider has dropped $30\sin 30^\circ = 15$ m.

Height above the ground $= 30 - 15 = 15$ m.`, sol: 'The midpoint of the line is at half the height.', scheme: [['Drop of 15 m', 1], ['15 m above ground', 1]], d: 3, c: 'analysis', t: [2], time: 120 }),
    ]),
  ],
}, (C) => { const top = [0, 30], land = [30 * S3, 0]; C.child('a').assert(is(top, land, 30), 'depression'); C.child('a').which([30 * S3, 20 * S3, 60, 15], Math.round(len(top, land) * 1e9) / 1e9); C.child('b').val(land[0], 0.01); C.child('c').assert(near(len(top, [30, 0]), 30 * S2), '45 line'); C.child('c').model([42.43]); const mid = [land[0] / 2, 15]; C.child('cii').assert(near(len(top, mid), 30), 'half way'); C.child('cii').model([15]); C.model([60, 51.96, 42.43, 15]); });

caseQ('c04', {
  passage: 'In the campus of Jantar Mantar, Jaipur, a guide uses a vertical 9 m pole to explain shadows. At different times of the day, the sun’s elevation is $30^\\circ$, $45^\\circ$ or $60^\\circ$.',
  d: 3, c: 'application',
  model: r`(a) Option (d): $9$ m. (b) $5.20$ m. (c) (i) $6\sqrt3 \approx 10.39$ m. Or (ii) $30$ m.`,
  sol: r`Shadow $= \dfrac{9}{\tan\theta}$: $9\sqrt3 \approx 15.59$ m at $30^\circ$, $9$ m at $45^\circ$, $3\sqrt3 \approx 5.20$ m at $60^\circ$.`,
  children: [
    child('a', mk.mcq({ stem: 'When the sun’s elevation is $45^\\circ$, the shadow of the pole is', opts: [r`$9\sqrt3$ m`, r`$3\sqrt3$ m`, r`$9\sqrt2$ m`, '$9$ m'], key: 'd', sol: r`$\tan 45^\circ = 1$, so the shadow equals the height, $9$ m.`, d: 1, c: 'understanding', t: [2], time: 45 })),
    child('b', mk.num({ stem: 'Find the shadow when the elevation is $60^\\circ$, in metres to two decimal places. (Use $\\sqrt3 \\approx 1.732$.)', value: 5.2, tol: 0.01, unit: 'm', sol: r`$\dfrac{9}{\sqrt3} = 3\sqrt3 \approx 5.20$ m.`, scheme: [['5.20 m', 1]], d: 2, c: 'understanding', t: [2], time: 75 })),
    child('c', mk.short({ marks: 2, stem: '**(i)** By how much does the shadow shorten from the $30^\\circ$ time to the $60^\\circ$ time?', model: r`$9\sqrt3 - 3\sqrt3 = 6\sqrt3 \approx 10.39$ m.`, sol: 'Subtract the two shadows.', scheme: [['Both shadows', 1], ['6√3 ≈ 10.39 m', 1]], d: 2, c: 'application', t: [2], time: 120 }), [
      mk.short({ marks: 2, stem: '**(ii)** At the moment the pole’s shadow is $9\\sqrt3$ m, a nearby tower casts a shadow $30\\sqrt3$ m long. How tall is the tower?', model: r`A shadow of $9\sqrt3$ m for the $9$ m pole means $\tan\theta = \dfrac{9}{9\sqrt3} = \dfrac{1}{\sqrt3}$: the sun is at $30^\circ$.

Tower height $= 30\sqrt3 \tan 30^\circ = 30\sqrt3 \times \dfrac{1}{\sqrt3} = 30$ m.`, sol: 'Same sun, same angle, for every object at that moment.', scheme: [['Sun at 30°', 1], ['Tower 30 m', 1]], d: 3, c: 'analysis', t: [2], time: 150 }),
    ]),
  ],
}, (C) => { const sh = (t) => 9 / Math.tan((t * Math.PI) / 180); C.child('a').which([9 * S3, 3 * S3, 9 * S2, 9], Math.round(sh(45) * 1e9) / 1e9); C.child('b').val(sh(60), 0.01); C.child('c').model([10.39]); C.child('c').assert(near(sh(30) - sh(60), 6 * S3), 'shortening'); C.child('cii').assert(is([30 * S3, 0], [0, 30], 30) && is([9 * S3, 0], [0, 9], 30), 'same sun'); C.child('cii').model([30]); C.model([9, 5.2, 10.39, 30]); });

caseQ('c05', {
  passage: 'A forest ranger is on a 20 m fire-watch tower near Dehradun. She spots smoke from one fire at an angle of depression of $30^\\circ$ and, in the opposite direction along a straight fire line through the foot of the tower, a second fire at an angle of depression of $45^\\circ$.',
  d: 3, c: 'application',
  model: r`(a) Option (b): $20\sqrt3$ m. (b) $20$ m. (c) (i) $20(\sqrt3 + 1) \approx 54.64$ m. Or (ii) $20(\sqrt3 - 1) \approx 14.64$ m.`,
  sol: r`First fire: $\dfrac{20}{\tan 30^\circ} = 20\sqrt3 \approx 34.64$ m. Second fire: $\dfrac{20}{\tan 45^\circ} = 20$ m.`,
  children: [
    child('a', mk.mcq({ stem: 'The distance of the first fire from the foot of the tower is', opts: ['$20$ m', r`$20\sqrt3$ m`, r`$\dfrac{20}{\sqrt3}$ m`, '$40$ m'], key: 'b', sol: r`$\tan 30^\circ = \dfrac{20}{d} \Rightarrow d = 20\sqrt3$ m. Option (c) uses $\tan 60^\circ$; option (d) is the line of sight.`, d: 2, c: 'understanding', t: [2], time: 60 })),
    child('b', mk.num({ stem: 'How far is the second fire from the foot of the tower (in metres)?', value: 20, unit: 'm', sol: r`$\tan 45^\circ = 1$, so the distance equals the height: $20$ m.`, scheme: [['20 m', 1]], d: 1, c: 'understanding', t: [2], time: 45 })),
    child('c', mk.short({ marks: 2, stem: '**(i)** How far apart are the two fires? (Use $\\sqrt3 \\approx 1.732$.)', model: r`They are on opposite sides of the tower, so add: $20\sqrt3 + 20 = 20(\sqrt3 + 1) \approx 54.64$ m.`, sol: 'Opposite sides: add the distances.', scheme: [['Sum of distances', 1], ['≈ 54.64 m', 1]], d: 2, c: 'application', t: [2], time: 120 }), [
      mk.short({ marks: 2, stem: '**(ii)** If both fires had been on the same side of the tower, how far apart would they be?', model: r`Same side: subtract: $20\sqrt3 - 20 = 20(\sqrt3 - 1) \approx 14.64$ m.`, sol: 'Same side: subtract the distances.', scheme: [['Difference of distances', 1], ['≈ 14.64 m', 1]], d: 2, c: 'analysis', t: [2], time: 120 }),
    ]),
  ],
}, (C) => { const T = [0, 20], F1 = [20 * S3, 0], F2 = [-20, 0]; C.child('a').assert(is(T, F1, 30) && is(T, F2, 45), 'scene'); C.child('a').which([20, 20 * S3, 20 / S3, 40], F1[0]); C.child('b').val(-F2[0]); C.child('c').model([54.64]); C.child('cii').model([14.64]); C.model(['20\\sqrt3', 20, 54.64, 14.64]); });
